+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  if (!isValidOptionalLimit(message.limit)) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+
+  const cursor = parseOptionalBefore(message.before);
+  if (cursor === null) {
+    return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
+  }
+
+  return {
+    valid: true,
+    data: {
+      type: 'list_sessions',
+      ...(message.limit !== undefined ? {limit: message.limit} : {}),
+      ...(cursor !== undefined ? {before: cursor} : {}),
+    },
+  };
+}
+
+function isValidOptionalLimit(limit: unknown): limit is number | undefined {
+  if (limit === undefined) return true;
+  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
+}
+
+function parseOptionalBefore(before: unknown): SessionCursor | undefined | null {
+  if (before === undefined) return undefined;
+  if (typeof before !== 'object' || before === null) return null;
+
+  const candidate = before as Record<string, unknown>;
+  if (!isValidSessionId(candidate.sessionId) || !isValidCursorTimestamp(candidate.updatedAt)) {
+    return null;
+  }
+
+  return {
+    updatedAt: candidate.updatedAt,
+    sessionId: candidate.sessionId,
+  };
+}
+
+function isValidSessionId(sessionId: unknown): sessionId is string {
+  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
+  return Number.isFinite(new Date(updatedAt).getTime());
+}
